+  virtual bool cpu_supports_evex() const = 0;
+  virtual bool supports_evex() const = 0;
+  virtual bool supports_f16c() const = 0;
+  virtual bool supports_fma() const = 0;
+  virtual bool supports_gfni() const = 0;
